export default "/* three-way-diff-editor — VS Code style. Editors are CodeMirror 6; colours are CSS variables. */\n\n.three-way-diff-container {\n  --twd-font-ui: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, Ubuntu, 'Droid Sans', sans-serif;\n  --twd-gap: 18px;\n\n  --twd-bg: #ffffff;\n  --twd-chrome-bg: #f8f8f8;\n  --twd-chrome-fg: #3b3b3b;\n  --twd-chrome-muted: #6f6f6f;\n  --twd-border: #e5e5e5;\n  --twd-editor-bg: #ffffff;\n  --twd-editor-fg: #1f1f1f;\n  --twd-line-number: #6e7681;\n  --twd-line-number-active: #171184;\n  --twd-active-line: rgba(0, 0, 0, 0.035);\n  --twd-cursor: #000000;\n  --twd-selection: #add6ff;\n  --twd-selection-match: rgba(173, 214, 255, 0.5);\n  --twd-bracket-match: #b9b9b9;\n  --twd-search-match: rgba(234, 92, 0, 0.33);\n  --twd-search-match-selected: rgba(166, 214, 255, 0.9);\n  --twd-panel-bg: #f8f8f8;\n  --twd-focus: #005fb8;\n\n  --twd-btn-bg: #ffffff;\n  --twd-btn-fg: #3b3b3b;\n  --twd-btn-border: #cecece;\n  --twd-btn-hover-bg: #ebebeb;\n  --twd-primary: #005fb8;\n  --twd-primary-fg: #ffffff;\n  --twd-primary-hover: #0258a8;\n\n  --twd-added-line: rgba(155, 185, 85, 0.22);\n  --twd-added-char: rgba(156, 204, 44, 0.45);\n  --twd-removed-line: rgba(255, 0, 0, 0.12);\n  --twd-removed-char: rgba(255, 0, 0, 0.3);\n  --twd-modified-line: rgba(255, 166, 0, 0.13);\n  --twd-placeholder-stripe: rgba(0, 0, 0, 0.07);\n  --twd-hover-line: rgba(212, 163, 115, 0.16);\n  --twd-inserted-line: rgba(0, 95, 184, 0.07);\n\n  --twd-accent-conflict: #e2a000;\n  --twd-accent-left: #d1242f;\n  --twd-accent-right: #2da44e;\n  --twd-accent-manual: #005fb8;\n\n  --twd-connector-added: #81b88b;\n  --twd-connector-removed: #e5534b;\n  --twd-connector-modified: #e2a000;\n  --twd-connector-hover: #d4a373;\n\n  --twd-stat-added: #2b7a34;\n  --twd-stat-removed: #b01b1b;\n  --twd-stat-modified: #895503;\n  --twd-stat-conflicts: #c4314b;\n\n  --twd-collapsed-bg: #f3f3f3;\n  --twd-collapsed-fg: #6f6f6f;\n  --twd-status-bg: #005fb8;\n  --twd-status-fg: #ffffff;\n\n  display: flex;\n  flex-direction: column;\n  height: calc(100vh - 150px);\n  position: relative;\n  box-sizing: border-box;\n  overflow: hidden;\n  border: 1px solid var(--twd-border);\n  background: var(--twd-bg);\n  color: var(--twd-chrome-fg);\n  font-family: var(--twd-font-ui);\n  font-size: 13px;\n}\n\n.three-way-diff-container[data-theme='dark'] {\n  --twd-bg: #1f1f1f;\n  --twd-chrome-bg: #181818;\n  --twd-chrome-fg: #cccccc;\n  --twd-chrome-muted: #9d9d9d;\n  --twd-border: #2b2b2b;\n  --twd-editor-bg: #1f1f1f;\n  --twd-editor-fg: #d4d4d4;\n  --twd-line-number: #6e7681;\n  --twd-line-number-active: #cccccc;\n  --twd-active-line: rgba(255, 255, 255, 0.04);\n  --twd-cursor: #aeafad;\n  --twd-selection: #264f78;\n  --twd-selection-match: rgba(173, 214, 255, 0.15);\n  --twd-bracket-match: #888888;\n  --twd-search-match: rgba(234, 92, 0, 0.33);\n  --twd-search-match-selected: rgba(81, 92, 106, 0.9);\n  --twd-panel-bg: #252526;\n  --twd-focus: #0078d4;\n\n  --twd-btn-bg: #313131;\n  --twd-btn-fg: #cccccc;\n  --twd-btn-border: #3c3c3c;\n  --twd-btn-hover-bg: #3c3c3c;\n  --twd-primary: #0078d4;\n  --twd-primary-fg: #ffffff;\n  --twd-primary-hover: #026ec1;\n\n  --twd-added-line: rgba(155, 185, 85, 0.2);\n  --twd-added-char: rgba(156, 204, 44, 0.35);\n  --twd-removed-line: rgba(255, 0, 0, 0.2);\n  --twd-removed-char: rgba(255, 0, 0, 0.4);\n  --twd-modified-line: rgba(255, 166, 0, 0.14);\n  --twd-placeholder-stripe: rgba(204, 204, 204, 0.1);\n  --twd-hover-line: rgba(212, 163, 115, 0.18);\n  --twd-inserted-line: rgba(0, 120, 212, 0.14);\n\n  --twd-accent-conflict: #cca700;\n  --twd-accent-left: #f85149;\n  --twd-accent-right: #3fb950;\n  --twd-accent-manual: #3794ff;\n\n  --twd-stat-added: #81b88b;\n  --twd-stat-removed: #f48771;\n  --twd-stat-modified: #e2c08d;\n  --twd-stat-conflicts: #f48771;\n\n  --twd-collapsed-bg: #252526;\n  --twd-collapsed-fg: #9d9d9d;\n  --twd-status-bg: #0078d4;\n}\n\n/* ------------------------------------------------------------------ buttons */\n\n.twd-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  height: 26px;\n  padding: 0 12px;\n  border: 1px solid var(--twd-btn-border, #cecece);\n  border-radius: 2px;\n  background: var(--twd-btn-bg, #fff);\n  color: var(--twd-btn-fg, #3b3b3b);\n  font-family: inherit;\n  font-size: 12px;\n  line-height: 1;\n  white-space: nowrap;\n  cursor: pointer;\n  transition: background-color 0.1s ease;\n}\n.twd-btn:hover:not(:disabled) {\n  background: var(--twd-btn-hover-bg, #ebebeb);\n}\n.twd-btn:focus-visible {\n  outline: 1px solid var(--twd-focus, #005fb8);\n  outline-offset: 1px;\n}\n.twd-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n.twd-btn-sm {\n  height: 22px;\n  padding: 0 8px;\n}\n.twd-btn-primary {\n  background: var(--twd-primary, #005fb8);\n  border-color: var(--twd-primary, #005fb8);\n  color: var(--twd-primary-fg, #fff);\n}\n.twd-btn-primary:hover:not(:disabled) {\n  background: var(--twd-primary-hover, #0258a8);\n}\n\n/* ------------------------------------------------------------------ toolbar & headers */\n\n.three-way-diff-container .diff-toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  align-items: center;\n  gap: 8px 16px;\n  padding: 6px 10px;\n  background: var(--twd-chrome-bg);\n  border-bottom: 1px solid var(--twd-border);\n  flex-shrink: 0;\n}\n.three-way-diff-container .diff-toolbar .toolbar-left {\n  display: flex;\n  gap: 6px;\n}\n.three-way-diff-container .diff-stats {\n  font-size: 12px;\n  color: var(--twd-chrome-muted);\n  font-variant-numeric: tabular-nums;\n}\n.three-way-diff-container .stat-added {\n  color: var(--twd-stat-added);\n}\n.three-way-diff-container .stat-removed {\n  color: var(--twd-stat-removed);\n}\n.three-way-diff-container .stat-modified {\n  color: var(--twd-stat-modified);\n}\n.three-way-diff-container .stat-conflicts {\n  color: var(--twd-stat-conflicts);\n  font-weight: 600;\n}\n\n.three-way-diff-container .diff-headers,\n.three-way-diff-container .diff-panels {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) var(--twd-gap) minmax(0, 1fr) var(--twd-gap) minmax(0, 1fr);\n}\n.three-way-diff-container .diff-headers {\n  background: var(--twd-chrome-bg);\n  border-bottom: 1px solid var(--twd-border);\n  flex-shrink: 0;\n}\n.three-way-diff-container .panel-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  height: 34px;\n  padding: 0 12px;\n  box-sizing: border-box;\n  font-size: 12px;\n  color: var(--twd-chrome-muted);\n  border-top: 1px solid transparent;\n  min-width: 0;\n}\n.three-way-diff-container .panel-header-title {\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n.three-way-diff-container .panel-header.left {\n  grid-column: 1;\n}\n.three-way-diff-container .panel-header.middle {\n  grid-column: 3;\n  color: var(--twd-chrome-fg);\n  background: var(--twd-editor-bg);\n  border-top-color: var(--twd-primary);\n}\n.three-way-diff-container .panel-header.right {\n  grid-column: 5;\n}\n.three-way-diff-container .header-actions {\n  display: flex;\n  gap: 6px;\n  flex-shrink: 0;\n}\n\n/* ------------------------------------------------------------------ panes */\n\n.three-way-diff-container .diff-panels {\n  flex: 1;\n  min-height: 0;\n  position: relative;\n}\n.three-way-diff-container .diff-panel {\n  position: relative;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n  background: var(--twd-editor-bg);\n}\n.three-way-diff-container .twd-gap {\n  background: var(--twd-chrome-bg);\n  border-left: 1px solid var(--twd-border);\n  border-right: 1px solid var(--twd-border);\n}\n.three-way-diff-container .connector-canvas {\n  position: absolute;\n  top: 0;\n  left: 0;\n  z-index: 5;\n  pointer-events: none;\n}\n.three-way-diff-container .twd-structured,\n.three-way-diff-container .twd-free {\n  height: 100%;\n}\n.three-way-diff-container .twd-free,\n.three-way-diff-container.is-free-editing .twd-structured {\n  display: none;\n}\n.three-way-diff-container.is-free-editing .twd-free {\n  display: block;\n}\n.three-way-diff-container .diff-panel .cm-editor {\n  height: 100%;\n}\n/* Only the right pane shows a scrollbar; the panes scroll together. */\n.three-way-diff-container .left-panel .cm-scroller,\n.three-way-diff-container .twd-structured .cm-scroller {\n  scrollbar-width: none;\n}\n.three-way-diff-container .left-panel .cm-scroller::-webkit-scrollbar,\n.three-way-diff-container .twd-structured .cm-scroller::-webkit-scrollbar {\n  display: none;\n}\n\n/* ------------------------------------------------------------------ diff lines\n   Never add borders or vertical padding to lines: every pane must keep the same line height. */\n\n.three-way-diff-container .cm-line.removed-line {\n  background-color: var(--twd-removed-line);\n}\n.three-way-diff-container .cm-line.added-line {\n  background-color: var(--twd-added-line);\n}\n.three-way-diff-container .cm-line.modified-line {\n  background-color: var(--twd-modified-line);\n}\n.three-way-diff-container .cm-line.twd-placeholder {\n  background-image: repeating-linear-gradient(\n    -45deg,\n    var(--twd-placeholder-stripe) 0,\n    var(--twd-placeholder-stripe) 1px,\n    transparent 1px,\n    transparent 7px\n  );\n}\n.three-way-diff-container .char-diff {\n  border-radius: 2px;\n}\n.three-way-diff-container .char-diff.char-removed {\n  background-color: var(--twd-removed-char);\n}\n.three-way-diff-container .char-diff.char-added {\n  background-color: var(--twd-added-char);\n}\n\n.three-way-diff-container .cm-line.merged-line.code-block-removed {\n  background-color: var(--twd-removed-line);\n}\n.three-way-diff-container .cm-line.merged-line.code-block-added {\n  background-color: var(--twd-added-line);\n}\n.three-way-diff-container .cm-line.merged-line.code-block-modified {\n  background-color: var(--twd-modified-line);\n}\n.three-way-diff-container .cm-line.merged-line.has-conflict {\n  box-shadow: inset 3px 0 0 var(--twd-accent-conflict);\n}\n.three-way-diff-container .cm-line.merged-line.has-conflict.from-left.twd-resolved {\n  box-shadow: inset 3px 0 0 var(--twd-accent-left);\n}\n.three-way-diff-container .cm-line.merged-line.has-conflict.from-right.twd-resolved {\n  box-shadow: inset 3px 0 0 var(--twd-accent-right);\n}\n.three-way-diff-container .cm-line.merged-line.has-conflict.from-manual {\n  box-shadow: inset 3px 0 0 var(--twd-accent-manual);\n}\n.three-way-diff-container .cm-line.merged-line.twd-inserted {\n  background-color: var(--twd-inserted-line);\n  box-shadow: inset 3px 0 0 var(--twd-accent-manual);\n}\n.three-way-diff-container .cm-line.twd-hover {\n  background-image: linear-gradient(var(--twd-hover-line), var(--twd-hover-line));\n}\n.three-way-diff-container .cm-line.twd-placeholder.twd-hover {\n  background-image:\n    linear-gradient(var(--twd-hover-line), var(--twd-hover-line)),\n    repeating-linear-gradient(\n      -45deg,\n      var(--twd-placeholder-stripe) 0,\n      var(--twd-placeholder-stripe) 1px,\n      transparent 1px,\n      transparent 7px\n    );\n}\n\n/* ------------------------------------------------------------------ merge action gutters */\n\n.three-way-diff-container .twd-actions .cm-gutterElement {\n  display: flex;\n  align-items: center;\n  padding: 0 3px;\n}\n.three-way-diff-container .twd-action-cell {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n}\n.three-way-diff-container .twd-action,\n.three-way-diff-container .twd-action-slot {\n  flex: none;\n  width: 16px;\n  height: 16px;\n}\n.three-way-diff-container .twd-action {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n  border: 1px solid transparent;\n  border-radius: 3px;\n  background: transparent;\n  color: var(--twd-chrome-muted);\n  font-family: var(--twd-font-ui);\n  font-size: 11px;\n  line-height: 1;\n  cursor: pointer;\n}\n.three-way-diff-container .twd-action:hover {\n  background: var(--twd-btn-hover-bg);\n  border-color: var(--twd-btn-border);\n  color: var(--twd-chrome-fg);\n}\n.three-way-diff-container .twd-action:focus-visible {\n  outline: 1px solid var(--twd-focus);\n}\n.three-way-diff-container .twd-action-block {\n  color: var(--twd-primary);\n  font-size: 9px;\n}\n.three-way-diff-container .twd-action-line {\n  opacity: 0.6;\n}\n.three-way-diff-container .twd-action-line:hover,\n.three-way-diff-container .twd-action-line.active {\n  opacity: 1;\n}\n.three-way-diff-container .twd-action-line.active {\n  color: var(--twd-primary);\n  border-color: var(--twd-primary);\n}\n\n/* ------------------------------------------------------------------ collapsed regions\n   Height must equal COLLAPSE_WIDGET_HEIGHT (cm/collapse.ts) in every pane. */\n\n.three-way-diff-container .collapsed-row {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  height: 36px;\n  padding: 0 8px;\n  box-sizing: border-box;\n  border-top: 1px solid var(--twd-border);\n  border-bottom: 1px solid var(--twd-border);\n  background: var(--twd-collapsed-bg);\n  color: var(--twd-collapsed-fg);\n  font-family: var(--twd-font-ui);\n  font-size: 12px;\n  user-select: none;\n  overflow: hidden;\n}\n.three-way-diff-container .collapsed-row .collapsed-row-placeholder {\n  font-size: 16px;\n  line-height: 1;\n  opacity: 0.7;\n}\n.three-way-diff-container .collapsed-row .collapsed-row-controls {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  width: 100%;\n  min-width: 0;\n}\n.three-way-diff-container .collapsed-row .collapse-buttons-right {\n  display: flex;\n  gap: 4px;\n}\n\n/* ------------------------------------------------------------------ status bar legend */\n\n.three-way-diff-container .diff-footer {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  height: 22px;\n  padding: 0 10px;\n  flex-shrink: 0;\n  background: var(--twd-status-bg);\n  color: var(--twd-status-fg);\n  font-size: 12px;\n}\n.three-way-diff-container .diff-legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n.three-way-diff-container .legend-swatch {\n  display: inline-block;\n  width: 10px;\n  height: 10px;\n  border-radius: 2px;\n  border: 1px solid rgba(255, 255, 255, 0.6);\n}\n.three-way-diff-container .legend-added .legend-swatch {\n  background: var(--twd-connector-added);\n}\n.three-way-diff-container .legend-removed .legend-swatch {\n  background: var(--twd-connector-removed);\n}\n.three-way-diff-container .legend-modified .legend-swatch {\n  background: var(--twd-connector-modified);\n}\n\n/* ------------------------------------------------------------------ save modal */\n\n.three-way-diff-container .twd-modal-mask {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  padding-top: 15vh;\n  background: rgba(0, 0, 0, 0.35);\n}\n.three-way-diff-container .twd-modal-wrap {\n  z-index: 1001;\n  outline: none;\n}\n.three-way-diff-container .twd-modal {\n  width: 420px;\n  max-width: calc(100vw - 32px);\n  border: 1px solid var(--twd-border);\n  border-radius: 4px;\n  background: var(--twd-panel-bg);\n  color: var(--twd-chrome-fg);\n  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);\n}\n.three-way-diff-container .twd-modal-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 10px 14px;\n  border-bottom: 1px solid var(--twd-border);\n}\n.three-way-diff-container .twd-modal-title {\n  font-weight: 600;\n}\n.three-way-diff-container .twd-modal-close {\n  border: none;\n  background: transparent;\n  color: inherit;\n  font-size: 18px;\n  line-height: 1;\n  cursor: pointer;\n}\n.three-way-diff-container .twd-modal-body {\n  padding: 14px;\n}\n.three-way-diff-container .twd-modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--twd-border);\n}\n";
